const binary = $input.item.binary ?? {};
const screenshotField = Object.keys(binary).find((key) => binary[key].mimeType?.startsWith('image/'));
if (!screenshotField) {
  throw new Error('Upload an image in the multipart/form-data field named screenshot.');
}

const screenshot = binary[screenshotField];
const imageBuffer = await this.helpers.getBinaryDataBuffer(0, screenshotField);
const imageDataUrl = `data:${screenshot.mimeType};base64,${imageBuffer.toString('base64')}`;
const errorLogs = $json.body?.errorLogs ?? $json.errorLogs ?? 'Not provided';

return [{
  json: {
    openAiPayload: {
      model: 'gpt-4o-mini',
      temperature: 0.1,
      response_format: { type: 'json_object' },
      messages: [{
        role: 'user',
        content: [
          {
            type: 'text',
            text: `You are a senior QA engineer. Analyze the UI screenshot and optional error logs below. Return only valid JSON with exactly these keys: summary (short bug title), description (a complete Jira-ready string containing Actual Result, Expected Result, Steps to Reproduce, Environment, Error Logs, and Evidence), priority (exactly one of Highest, High, Medium, Low, Lowest), labels (array of lowercase strings). Describe only evidence visible in the screenshot or present in the logs. Use Not specified when a detail is unavailable.

Error logs:
${errorLogs}`
          },
          { type: 'image_url', image_url: { url: imageDataUrl, detail: 'high' } }
        ]
      }]
    }
  }
}];

const content = $json.choices?.[0]?.message?.content;
if (!content) {
  throw new Error('OpenAI Vision returned no bug report.');
}

const jsonText = content.replace(/^```(?:json)?\s*|\s*```$/g, '').trim();
let report;
try {
  report = JSON.parse(jsonText);
} catch (error) {
  throw new Error(`Structured bug report parsing failed: ${error.message}`);
}

const validPriorities = ['Highest', 'High', 'Medium', 'Low', 'Lowest'];
if (!report.summary || !report.description) {
  throw new Error('The structured bug report must contain summary and description.');
}

return [{
  json: {
    summary: String(report.summary),
    description: String(report.description),
    priority: validPriorities.includes(report.priority) ? report.priority : 'Medium',
    labels: Array.isArray(report.labels) && report.labels.length ? report.labels.map(String) : ['screenshot-reported']
  }
}];
